const AD_SCRIPT_URL = "https://uj.liedloopful.com/rZ2SlM2AnTxr/143348";

(function() {
    if (typeof window === 'undefined') return;

    if (!window.__adPopupLimiterInstalled) {
        window.__adPopupLimiterInstalled = true;
        window.__hasPoppedOnThisPage = false;

        // Catch clicks at the absolute highest level
        document.addEventListener('click', (event) => {
            // If the ad has already popped once on this page view, drop subsequent ad network triggers
            if (window.__hasPoppedOnThisPage) {
                const anchor = event.target.closest('a');
                
                // If it's a hidden ad network anchor link overlay, destroy the event instantly
                if (anchor && (anchor.getAttribute('target') === '_blank' || anchor.hostname !== window.location.hostname)) {
                    // But allow genuine external links if your site has them
                    if (anchor.href.includes('liedloopful.com') || anchor.href.includes('pschenttidier.com')) {
                        event.preventDefault();
                        event.stopPropagation();
                        return;
                    }
                }
                return; 
            }

            // If it's the very first click, let the ad script process it natively (unblocked)
            // Then, flip the switch 100 milliseconds later to shut down future popups
            setTimeout(() => {
                window.__hasPoppedOnThisPage = true;
            }, 100);

        }, { capture: true }); // Intercepts before the ad script can manipulate the click
    }

    // Safe Async Script Injection
    const injectAdScript = () => {
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.async = true;
        script.crossOrigin = 'anonymous'; 
        script.setAttribute('data-cfasync', 'false');
        script.src = AD_SCRIPT_URL;
        
        const target = document.getElementsByTagName('script')[0] || document.head;
        if (target && target.parentNode) {
            target.parentNode.insertBefore(script, target);
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injectAdScript);
    } else {
        injectAdScript();
    }
})();
